const u = $input.first().json;
const msg = u.message || u.edited_message || null;
const cq = u.callback_query || null;
const isCallback = !!cq;
const from = (cq ? cq.from : (msg ? msg.from : {})) || {};
const chat = (cq ? (cq.message && cq.message.chat) : (msg ? msg.chat : {})) || {};
const text = (!isCallback && msg && typeof msg.text === 'string') ? msg.text.trim() : '';
const callbackData = isCallback ? (cq.data || '') : '';

// TODO (Step 8): the two authorised telegram_user_id, as numbers.
// Leave empty => nobody is allowed (fail closed).
const AUTHORIZED_IDS = [];

const chatId = chat.id;
const fromId = from.id;
const privateOk = chat.type === 'private';
const authorised = AUTHORIZED_IDS.includes(fromId);

return [{ json: {
  chatId, fromId,
  chatType: chat.type,
  text, callbackData, isCallback,
  updateId: u.update_id,
  blocked: !(privateOk && authorised)
}}];

const j = $input.first().json;
let state = {};
try { state = j.stateRaw ? JSON.parse(j.stateRaw) : {}; } catch (e) {}
const step = state.step || 'IDLE';
const cb = j.callbackData || '';

const REG_STEPS = ['WAITING_EVENT_TYPE','WAITING_TRANSACTION_TEXT','WAITING_DATE','WAITING_DATE_MANUAL','WAITING_CONFIRMATION','PROCESSING'];
const inRegistration = REG_STEPS.indexOf(step) !== -1;
const inCorrection = step.indexOf('WAITING_CORRECTION') === 0 || step === 'PROCESSING_CORRECTION';
const freshCorregir = !j.isCallback && j.text === '/corregir';

let route;
if (j.blocked) route = 0;                                                    // blocked
else if (cb === 'pending:continue' || cb === 'pending:switch') route = 3;     // answered the 'unfinished registration' prompt
else if (freshCorregir && inRegistration) route = 4;                         // ask before discarding an in-progress registration (2.10 §20)
else if (freshCorregir || cb.indexOf('corr:') === 0 || inCorrection) route = 1;  // correction -> workflow B
else route = 2;                                                              // registration

return [{ json: Object.assign({}, j, { route, state }) }];

const j = $input.first().json;
const state = j.state || {};
const step = state.step || 'IDLE';
const cb = j.callbackData || '';

const LABELS = {
  mama_entrega_dinero: 'Mama me entrego dinero',
  erick_gasta_para_mama: 'Yo gaste para mama',
  erick_entrega_dinero: 'Yo le entregue dinero',
  mama_devuelve: 'Mama me devolvio dinero',
  erick_devuelve: 'Yo le devolvi dinero'
};
function kb(rows){return {rows: rows.map(r => ({row:{buttons: r.map(b => ({button:{text:b.t, additionalFields:{callback_data:b.d}}}))}}))};}
const K_EVENT = kb(Object.keys(LABELS).map(k => [{t: LABELS[k], d: 'evt:'+k}]));
const K_DATE  = kb([[{t:'Hoy',d:'date:hoy'},{t:'Ayer',d:'date:ayer'}],[{t:'Otra fecha',d:'date:otra'},{t:'Cancelar',d:'cancel'}]]);
const K_CONF  = kb([[{t:'CONFIRMAR',d:'confirm'},{t:'CANCELAR',d:'cancel'}]]);

function limaISO(off){
  const p = new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const d = new Date(p + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + (off||0));
  return d.toISOString().slice(0,10);
}
function out(o){ return [{ json: Object.assign({ chatId: j.chatId, leg:0, replyText:'', n8nKeyboard:null, redisAction:'keep', stateNext:null, apiBody:null }, o) }]; }

if (j.isCallback && cb === 'cancel')
  return out({ leg:0, redisAction:'del', replyText:'Operacion cancelada.' });

if (step === 'PROCESSING')
  return out({ leg:3 });

if (step === 'IDLE')
  return out({ leg:1, redisAction:'set', stateNext:{ step:'WAITING_EVENT_TYPE' },
    replyText:'Que ocurrio?', n8nKeyboard: K_EVENT });

if (step === 'WAITING_EVENT_TYPE') {
  if (j.isCallback && cb.indexOf('evt:') === 0)
    return out({ leg:0, redisAction:'set',
      stateNext:{ step:'WAITING_TRANSACTION_TEXT', event_type: cb.slice(4) },
      replyText:'Cuanto fue y en que?  Ejemplo:  S/ 35.50 taxi' });
  return out({ leg:1, replyText:'Elige una opcion del menu.', n8nKeyboard: K_EVENT });
}

if (step === 'WAITING_TRANSACTION_TEXT') {
  if (!j.isCallback && j.text)
    return out({ leg:1, redisAction:'set',
      stateNext: Object.assign({}, state, { step:'WAITING_DATE', pending_raw_text: j.text }),
      replyText:'De que fecha fue?', n8nKeyboard: K_DATE });
  return out({ leg:0, replyText:'Escribe el monto y una descripcion. Ej:  S/ 35.50 taxi' });
}

function summary(dateISO){
  const key = 'telegram:' + j.chatId + ':update:' + j.updateId;
  const next = Object.assign({}, state, { step:'WAITING_CONFIRMATION', pending_event_date: dateISO, pending_idempotency_key: key });
  const txt = 'Revisa tu registro:\n\n' + (LABELS[state.event_type] || state.event_type) + '\n' + state.pending_raw_text + '\nFecha: ' + dateISO + '\n\nEsta correcto?';
  return out({ leg:1, redisAction:'set', stateNext: next, replyText: txt, n8nKeyboard: K_CONF });
}

if (step === 'WAITING_DATE') {
  if (j.isCallback && cb === 'date:hoy')  return summary(limaISO(0));
  if (j.isCallback && cb === 'date:ayer') return summary(limaISO(-1));
  if (j.isCallback && cb === 'date:otra')
    return out({ leg:0, redisAction:'set',
      stateNext: Object.assign({}, state, { step:'WAITING_DATE_MANUAL' }),
      replyText:'Escribe la fecha como AAAA-MM-DD (ej: 2026-08-25).' });
  return out({ leg:1, replyText:'Elige una fecha.', n8nKeyboard: K_DATE });
}

if (step === 'WAITING_DATE_MANUAL') {
  if (!j.isCallback && /^\d{4}-\d{2}-\d{2}$/.test(j.text)) return summary(j.text);
  return out({ leg:0, replyText:'Formato invalido. Escribe la fecha como AAAA-MM-DD.' });
}

if (step === 'WAITING_CONFIRMATION') {
  if (j.isCallback && (cb === 'confirm' || cb === 'retry')) {
    const key = state.pending_idempotency_key || ('telegram:' + j.chatId + ':update:' + j.updateId);
    return out({ leg:2, redisAction:'set',
      stateNext: Object.assign({}, state, { step:'PROCESSING', pending_idempotency_key: key }),
      apiBody: {
        telegram_user_id: String(j.fromId),
        event_type: state.event_type,
        raw_text: state.pending_raw_text,
        event_date: state.pending_event_date,
        idempotency_key: key
      } });
  }
  return out({ leg:1, replyText:'Confirma o cancela la operacion.', n8nKeyboard: K_CONF });
}

return out({ leg:0, redisAction:'del', replyText:'Reiniciemos. Envia cualquier mensaje para empezar de nuevo.' });

const j = $input.first().json;
const state = j.state || {};
return [{ json: {
  chatId: j.chatId,
  stateNext: Object.assign({}, state, { pending_prompt: 'switch_to_correction' }),
  replyText: 'Tienes un registro sin terminar. Que quieres hacer?',
  n8nKeyboard: { rows: [ { row: { buttons: [
    { button: { text: 'Continuar registro', additionalFields: { callback_data: 'pending:continue' } } },
    { button: { text: 'Cancelar y corregir', additionalFields: { callback_data: 'pending:switch' } } }
  ] } } ] }
}}];

const j = $input.first().json;
const state = j.state || {};
if (j.callbackData === 'pending:switch') {
  return [{ json: {
    chatId: j.chatId, fromId: j.fromId, updateId: j.updateId,
    isCallback: false, text: '', callbackData: '',
    decision: 'switch', forceCorrection: true
  }}];
}
const clean = Object.assign({}, state);
delete clean.pending_prompt;
return [{ json: {
  chatId: j.chatId, decision: 'continue',
  stateNext: clean,
  replyText: 'Ok, seguimos con tu registro. Envia lo que faltaba.'
}}];

const r = $input.first().json;
const status = r.statusCode || (r.body ? 200 : 0);
const body = r.body || r;
const smState = $('Registro SM').item.json.stateNext || {};
const fromId = String($('Parse update').item.json.fromId);
const chatId = $('Parse update').item.json.chatId;

// TODO (Step 8): map each telegram_user_id -> the OTHER person's chat id.
// For a bot, a user's private chat id == their user id.
const OTHER = {};   // e.g. { "111": "222", "222": "111" }

if (status >= 200 && status < 300) {
  const t = body.transaction || {};
  const b = body.balance || {};
  const dir = b.direction === 'erick_owes_mama' ? 'Erick le debe a Mama'
           : b.direction === 'mama_owes_erick' ? 'Mama le debe a Erick'
           : 'No hay deuda pendiente';
  return [{ json: {
    ok: true, chatId,
    replyText: 'Registrado\n\n' + t.description + '  -  S/ ' + t.amount + '\n\nSaldo actualizado:\n' + dir + ': S/ ' + b.balance,
    notifyChatId: OTHER[fromId] || null,
    notifyText: 'La otra persona registro:\n\nS/ ' + t.amount + '  -  ' + t.description + '\n\nNo necesitas registrarlo de nuevo.',
    revertState: null
  }}];
}

const code = (body.error && body.error.code) || 'INTERNAL_ERROR';
const MSG = {
  PARSER_FAILED: 'No entendi el monto. Escribe algo como:  S/ 35.50 taxi',
  INVALID_AMOUNT: 'El monto no es valido (positivo, maximo 2 decimales).',
  INVALID_EVENT_DATE: 'La fecha no es valida o esta en el futuro.',
  INVALID_EVENT_TYPE: 'Tipo de operacion no reconocido.',
  UNKNOWN_TELEGRAM_USER: 'No estas autorizado para usar este bot.',
  DUPLICATE_IDEMPOTENCY_KEY: 'Esa operacion ya fue registrada con otros datos.'
};
return [{ json: {
  ok: false, chatId,
  replyText: MSG[code] || 'Hubo un problema. Intenta de nuevo en un momento.',
  revertState: Object.assign({}, smState, { step: 'WAITING_CONFIRMATION' }),
  notifyChatId: null
}}];
